import type { Language } from "./i18n";
import type { ControlTopic } from "./helpTopics";

export const controlHelpText: Record<Language, Record<ControlTopic, string>> = {
  en: {
    paneViews: "List shows the opened folder. Tree expands branches in the same pane. Use the disclosure button or the configured Left and Right row keys to collapse or expand a branch. Both panes remember their own view. Going back to List from a nested item opens its parent and keeps the item selected when available. If the parent cannot be opened, List shows the folder already open in the pane. Tree and background folder sizing are available for local folders. Expanded branches keep their visible contents during automatic and manual refresh. A warning on a branch means its contents may be out of date. Refresh again to retry.\n\nTurn on Folder sizes to calculate totals in the current pane. Refresh rechecks the current folder and keeps completed values until replacements are ready. In Tree, F3 on a folder measures only that branch, including its descendants. An ellipsis means a size is pending, a dash means it is unavailable, and ≥ marks a partial total. When supported, Size on disk shows allocation instead of logical file size. Turn Folder sizes off to stop the background scan. See [[paneSelection|Current row and marks]] and [[spaceAnalyzer|Space Analyzer]].",
    workspace: "The main menu is visible by default. To show it only when needed, clear Always show the main menu in Options → Appearance → Window. F9 or Alt brings focus to the menu by default. Use the arrow keys to browse, Enter to run a command, and Esc to return to the previous control. Left and Right open drives, panel modes, and sorting for that pane. Files works with the current or marked items. Commands opens search, comparison, folder shortcuts, and specialized views. Options opens preferences. Help opens this guide and can show release notes or the diagnostic log when available. Open the log with Help → Open error log, then choose File → Clear error log in the viewer and confirm. New errors continue to be recorded. In Help → About, choose the creator’s name to open hrynco.com in your browser. GitHub releases offer downloads and updates for Windows, Linux, and macOS. Choose Commands → Check for updates to check manually. When Dirlume is up to date, Donate via monobank opens Dirlume's donation jar in your browser.\n\nThe toolbar toggles [[quickView|Quick View]], opens [[gitView|Git View]] for a local repository and starts [[search|Find files]]. Swap panes exchanges the visible sides when both panes are available. Show hidden files changes visibility in both file panes. Toggle terminal opens or hides the shell and is unavailable while a document is open. The sun or moon switches to the favorite light or dark scheme. If enabled in Options, the scheme list lets you choose any installed scheme.\n\nDrag the pane divider to resize the panes. Use Left and Right when the divider has focus. Drag the terminal divider vertically or use the configured resize shortcuts. On Windows, the title-bar buttons minimize, maximize or restore, and close the window. The optional status bar shows the latest operation or error and the active location. See [[operations|File actions]] and [[files|Main File Panels]].\n\nThe Administrator badge beside Dirlume identifies a Windows window running with elevated permissions.",
    paneNavigation: "Back returns to the previous location in this pane and Forward revisits an entry after going back. An arrow is disabled when there is no destination in that direction. Back can also leave search results or the process list. The Parent folder button, the .. row, and the configured Parent folder shortcut open the immediate parent. In a local pane, Shift+Enter opens the focused folder in the system file manager. On .. it opens the current folder. For files, Shift+Enter works like Enter. The button is disabled and the row is hidden at a root, including saved connections lists. Use Back or a dimmed breadcrumb to return from a saved connections list.\n\nUse [[paneAddress|Address and breadcrumbs]] to jump to another location or [[paneSources|Drives and pane sources]] to change the source. Refresh reads the current folder again or reruns a local search in [[search|Search results]]. It is disabled while the pane is loading.",
    paneAddress: "The highlighted breadcrumb names the current folder or connection list. Choose an earlier segment to open an ancestor. Moving to a parent keeps the previous branch available as dimmed segments. Use the leading ellipsis, Show parent folders, to open a hidden ancestor. The trailing ellipsis, Show previous path, opens a hidden folder from the previous branch. Widen the pane to restore hidden segments. In remote file panes, the source breadcrumb and the current source in the pane’s sources menu both open saved connections and keep the previous path available. Back returns to the folder you left, and Forward reopens the list.\n\nClick the empty address area or the pencil to type a path. Use arrow keys to choose suggestions and Enter to open the typed or chosen folder. Esc restores the breadcrumbs. Copy path copies the displayed address without navigating. Saved connections and read-only indicators may show an address without editing it. See [[paneNavigation|Pane navigation]] and [[paneSources|Drives and pane sources]].",
    paneSources: "Use the drive-and-arrow button beside the address to open the source picker. Choose a drive, a saved place, a connection type, or Processes. Up and Down move between entries, Enter chooses one, and Esc closes the picker. Alt+F1 opens the left picker and Alt+F2 opens the right picker with the default shortcuts. The Left and Right main menus also offer the corresponding picker.\n\nThis computer lists local folders and drives. Dirlume LAN lists computers paired directly in Dirlume. KSwitcher LAN lists computers paired through KSwitcher and shows any permission messages for that connection.\n\nChoose Recent under Downloads to see the last 100 visited folders. Both panes use the same list. Filter by folder name, path, or source. Press Enter or double-click a folder to reopen it in that pane. Remove from Recent removes the selected history entry. Clear Recent removes the entire list.\n\nTwin panels and Classic commander show drive buttons directly above the file list. The highlighted drive or place contains the current folder. SMB is available on Windows, macOS, and Ubuntu. Connection providers may require a saved profile or permission to access a location. See [[remote|Remote connections]] and [[files|Main File Panels]]. Choose Collections, or press 6 in the source picker, to open saved collections. Use New collection to name one and F7 to create virtual folders inside it. To add references, open a collection folder in one pane, select files or folders in the other pane, and press F5. Confirm the virtual destination. Removing a reference or a virtual folder leaves the originals in place. To copy current originals, select their references or a virtual folder and use F5. Dirlume recreates the virtual hierarchy in a local folder and uses its usual copy conflict choices. If a provider is disconnected or an original is missing, the reference remains available for retry.",
    paneFilter: "Filter folder limits the visible entries in the current pane to matches in the current listing. It does not scan subfolders. Type in the filter field and press Enter to return to the list, or use Esc or Close filter to clear it. A count of zero means no visible entries match.\n\n[[search|Find files]] searches the chosen folder scope and puts matches in a separate results view. Quick search instead moves the current row among visible entries without changing the listing or marks. See [[files|Main File Panels]].",
    paneColumns: "The headings describe the values shown by the current panel mode. Click a sortable heading to change its order. The arrow shows the active column and direction. Right-click a heading or use its keyboard context menu to choose visible columns. Name stays visible. Brief and Medium group entries into columns and page through them together. Full, Wide, and other modes show different metadata.\n\nUse Left or Right → Sort modes for other sort keys, groups, and tie-breakers. Provider support determines which metadata can be sorted or displayed. Set list and status fields and widths under Options → Panel modes. Built-in modes use automatic widths. Set a width to 0 to fit the heading and values when the pane has space. Name fills the space left by the metadata columns. Character and percentage widths let you set your own layout. The Size column widens as needed to show complete folder measurements, including the unit. See [[files|Main File Panels]].",
    paneSelection: "The current row is the item under the cursor. Move it with the arrow keys or Quick search. Insert, Shift with the selection keys, and Ctrl-click or Command-click mark items. With Right-click selection enabled, a short right-click toggles a mark, dragging applies the starting row’s mark or unmark action to each new row, even when you reverse direction. Passing over a row again keeps its mark state. A stationary hold opens the context menu on release. The parent row cannot be marked. Marked rows keep their item icons and usual text weight. Current and marked names use the selection text color from the color scheme. Other names use their usual file colors. Name with mark also shows a checkmark. Press Space to clear all marks in the focused file list while keeping the current row. Change or disable Clear marks in Options → Keyboard shortcuts.\n\nBatch [[operations|file operations]] use marked items in the active pane when there are marks. Otherwise they use the current item. Open, Viewer, Editor, and Quick View work with the current file. The active marked row has its own outline and background, configurable in [[panels|panel appearance]].",
    paneStatus: "The footer can show the current item’s details, visible folder and file counts, and the number and total size of marked items. A ≥ before the marked size means the total is a lower bound. Unknown or unavailable metadata and partial results are identified when the source cannot provide everything. Search results show a match count.\n\nNavigation and size calculations show progress. Use the cancel button to stop the operation in that pane. Dismiss error clears its message. An access error can offer a separate elevated window on Windows or a retry with sudo for a supported SSH session. The free-space control shows volume or remote capacity when available and opens [[spaceScope|analysis scope]]. See [[files|Main File Panels]].\n\nWhen the system opens a local file, this area also shows a pending request, a brief handoff confirmation, or a reported error.",
    diskInformation: "Press Ctrl+Shift+L to show Disk information for the active folder’s volume or mounted share in the opposite pane. On macOS, Command+Shift+L also works. Invoke the shortcut again to close Disk information and restore the view that pane was showing. The source folder stays visible. Change or disable the binding in Options → Keyboard shortcuts.\n\nThe view reads the root, volume label, filesystem, and capacity without scanning files. Choose Scan volume or Scan share to measure files from that root in [[spaceAnalyzer|Space Analyzer]].",
    spaceSunburst: "Sunburst shows the selected folder in the center, its children in the inner ring, and their children in the outer ring. The item list gives the same names, sizes, and shares. Select a folder to drill down or a file to see its details. Right-click or press Shift+F10 on an item for actions. Explicitly choosing a view saves it for future scans.",
    spaceAnalyzer: "Space Analyzer scans a folder, volume, share, or connection root in the pane you choose. Local APFS and ext4 scans use faster metadata reads where supported. This also speeds up Scan volume, F3, and background Folder sizes in List and Tree. Select Space Analyzer in the Left or Right menu to open it in either or both panes. Read the [[spacePath|current folder path]] or choose a larger [[spaceScope|scan scope]]. Switch between [[spaceTree|Tree]] and [[spaceTreemap|Treemap]] as results arrive. See [[spaceMetric|size metrics]].",
    spaceScope: "Click Analyze space or the free-space figure for the folder shown in that file pane. When capacity is available, the meter shows the used fraction and the text shows free space. Paired Dirlume drives and KSwitcher LAN drives show these figures when the host reports capacity. Hover over the control or focus it with Tab to see the free, total, and used space. The arrow beside it can scan the containing volume, share, or saved connection root if its boundary is known. The scope menu shows the address before you start.\n\nSupported local folders and file-server locations can open the [[spaceAnalyzer|Space Analyzer]]. Sources such as archive listings and connection pickers do not offer a scan. The control is above the list in Twin panels and in the footer in other layouts.",
    spacePath: "The breadcrumbs show the current folder or the selected file’s parent. When the path fits, every segment is visible. In a narrow pane, choose Show parent folders to reach hidden ancestors. Choose an ancestor within the scan to reveal it and keep other branches expanded. An ancestor outside the scan starts a new scan. A successful directory change in the local terminal or matching SSH terminal follows the same rules.",
    spaceTree: "Tree lists the files and folders beneath the scan path. Click or use Up and Down to select a row. Click its disclosure arrow, double-click a folder, or use Right to expand it. Left collapses a branch or moves to its parent. Home and End go to the first and last visible row. The row size, bar, and percentage follow the current [[spaceMetric|size metric]]. For incomplete rows and actions see [[spaceActions|Scan controls and results]].\n\nIn the local tree, right-click a file or folder for its actions. F5 copies, F6 renames or moves, F8 follows the location’s Trash policy, and Shift+Delete opens permanent deletion. These shortcuts use the same settings as a file pane. The root is the scan scope and cannot be moved or deleted from the tree. See [[actionDialogs|file operation dialogs]].",
    spaceTreemap: "Each tile is an item in the displayed folder and its area reflects the current [[spaceMetric|size metric]]. Click a folder tile to drill down. Click a file tile to select it. The arrow above the map goes back to the parent and the heading shows the current folder and total. More items returns to Tree, which also shows entries with zero or unavailable size. The map shows no tiles when it has no positive results. See [[spaceAnalyzer|Space Analyzer]].",
    spaceMetric: "File size is the logical length of files. Size on disk is allocated storage. It can be larger because allocation uses blocks, or smaller for compressed or sparse files. Some sources provide only file size. When allocation data is available, switch metrics to update totals, row order, bars, and tile sizes. Shared allocation identifies storage counted once for hard-linked items.\n\nA percentage is the item’s share of its parent folder under the current metric. Equal percentages in different folders can therefore represent different byte counts. See [[spaceActions|Scan controls and results]] for zero and partial values or return to [[spaceAnalyzer|Space Analyzer]].",
    spaceActions: "Scanning… means results are still arriving. A complete 0 B means no bytes were found under the current metric. A dash means a value is unavailable. Partial results include accessible entries and can omit unreadable or unfinished branches. Reconnect before rescanning an interrupted remote scan.\n\nStop appears during a scan and keeps the results found so far. Rescan starts again from the same root. Show in other pane opens a selected folder there or reveals a selected file in its parent. It is unavailable if the scan failed. Close ends the analysis and restores the file pane. See [[spaceAnalyzer|Space Analyzer]].",
    quickView: "Quick View follows the current file in the opposite pane. Previous File and Next File move through files in the source pane's displayed order, skipping folders and stopping at either end. Alt+PageUp and Alt+PageDown do the same by default. Change or remove either shortcut in Options → Keyboard shortcuts. Rendered and Source switch the display for Markdown and HTML. In rendered Markdown, Ctrl-wheel zooms text and diagrams together. Choose Open diagram to inspect it separately. Binary files show byte characters and offsets. For images, Zoom in, Zoom out, and Fit to pane adjust the display. The rotation buttons only rotate the preview. Unsupported or unreadable files show an explanation. Close Quick View or use its shortcut again to restore the second file pane. Use [[viewer|Viewer]] to open a document tab.",
    gitView: "Open Git View from a local folder in a Git repository. The branch pane lists local and remote refs and marks the current branch. Filter branches limits that list. Selecting a branch shows its commit history in the other pane without checking it out. Expand a commit to see its details and changed paths, copy its hash, or load more history when available. Select Changes to review staged, unstaged, and untracked files across the working tree. Filter by path and use Up and Down to select a change. The opposite pane shows the inline diff. Staged changes compare HEAD with the index. Unstaged changes compare the index with the working file. Open in Viewer or Open in Editor opens the working file when available. Saving or selecting Refresh rereads changes.\n\nSelect a source branch and choose Merge branch. Review the source and current branch, then choose fast-forward only or create a merge commit. Merge in progress lists unresolved paths from Git, including after reopening the app. Compare Base, Ours, and Theirs. Choose a side, or edit and stage the working result. Continue after resolving every path, or confirm Abort merge.\n\nOpen History actions to cherry-pick, revert, reset, rebase, view the reflog, or force-push with lease. Open a commit’s details and select Use in history actions to fill its ID. Review the target and the affected paths. For rebase, select a base, move commits in the sequence, and choose Pick, Reword, Squash, or Drop. Reopening Git View restores suspended operations so you can resolve conflicts and continue or abort. Reflog recovery creates a new branch at the selected commit. Force-push with lease displays the destination and expected remote tip for confirmation.\n\nUse the branch actions to create a local branch from the selected commit, switch to a local branch, rename or safely delete a branch, or create and switch to a branch that tracks the selected remote branch. Review the repository and branch before confirming.\n\nChoose Compare revisions in the history pane. Select branches, tags, or enter full commit IDs. Compare lists unique commits on both sides and changed paths from base to target. Select a path to inspect its inline diff. The checkout stays intact. Open Commit graph to search commit messages on the selected branch. Open File history and enter a path relative to the repository to view its commits or blame at the selected revision.\n\nUse Stage hunk or Unstage hunk to inspect and update one text hunk. Select files lets you review several paths together. Discard shows the path and working diff before restoring it from the index or removing an untracked file. Amend replaces the current commit after you review the index and message. Stashes lets you save the working and staged versions, preview a stash, apply it, pop it after a successful application, or confirm its removal. Enable Restore staged changes to the index to restore the index. Git View shows any remaining conflicts.\n\nUse Stage or Unstage on the selected file in the preview pane. Stage adds the current working version and asks before replacing an existing staged version. Unstage restores the index for that path and keeps the working file. In Changes, Commit lists every staged path, including paths hidden by the filter. Select a path to review its staged diff, enter a message, and confirm. Git creates a local commit on the checked-out branch. Cancel keeps the draft in the current Git View session. If the index or branch changes, review the refreshed list before committing again. Git hooks and signing run with the repository configuration. Use a terminal if they require input. A hook that changes the proposed commit contents stops the commit. Close Git View returns to [[files|Main File Panels]].",
    environment: "Choose an environment scope to list variables and filter by name. System, user, and login shell choices depend on the platform. Click a column heading to sort, or use Quick search to move within the visible list. Parent folder returns to scopes and Back to files restores the pane. Refresh rereads that scope.\n\nInspect reads the selected value. Edit and New variable write to an editable scope and may require permission. Copy opens a review when the opposite pane is an editable environment scope. It uses marked variables or the current one and lets you review collisions before saving. Login shell integration is offered where supported. The [[terminal|terminal]] indicates when its environment needs a reload.",
    actionDialogs: "Commands → File operation history shows the session’s latest copies and moves. Undo and Redo apply to verified regular files copied or moved locally to one destination without overwriting. Undo Copy moves the created copies to Trash. If a reversal stops partway through, Retry applies to the remaining files. A new transfer that changes files clears Redo.\n\nA copy or move dialog lists the source selection and destination. Change the path or use the folder picker when available. Use the checkboxes below Existing files to set copy options such as preserving timestamps or filtering by file mask. Each checkbox sits to the left of its label. Click the label or press Space when the checkbox has focus. When uploading, check the FTP or SFTP connection next to the path. With a connected SSH folder in the other pane, F6 moves regular local files there. Each source is removed after its upload is committed. If removal fails, Retry checks the server file before attempting it again. Rename changes the item’s name in its parent. The conflict dialog tells you which destination already exists and offers only actions supported by the operation. Cancel leaves the pending change unapplied. For a longer Copy or Move, the progress dialog estimates the time left after five seconds when the remaining sizes and transfer speed are available. The estimate pauses while a conflict awaits your choice.\n\nTrash and permanent delete each show a confirmation. In a deletion batch, the progress dialog shows the current item and count. A recoverable failure offers retry, skip, or cancel for the remainder. On Windows a sharing violation may offer the locking-process list. Read prompts before choosing an action. See [[operations|File operations]] and [[paneSelection|Current row and marks]].",
    fileBookmarks: "Click beside a line number or use Bookmark line in the local text Viewer. In rendered Markdown, select a passage and choose Navigate → Bookmark selection. Source and Preview use the same configurable bookmark shortcut. File bookmarks in the Viewer and Commands → File bookmarks open the same movable window. Bookmarks are grouped by file, including closed files. Drag the title bar to move the window. It stays open when you work in Dirlume or jump to a bookmark. Choose an entry and press Enter to open its saved source line or highlight the passage in Preview. If a passage cannot be located, its bookmark stays in the list. The list also lets you name and remove bookmarks.",
  },
  uk: {
    paneViews: "Список показує відкриту папку. Дерево розгортає гілки в тій самій панелі. Скористайтеся кнопкою розгортання або налаштованими клавішами вліво й вправо. Кожна панель пам’ятає власний вигляд. Повернення до списку з вкладеного елемента відкриває його батьківську папку та зберігає виділення, якщо елемент доступний. Якщо батьківську папку відкрити не вдалося, список показує папку, відкриту в панелі. Дерево й фонові розміри доступні для локальних папок. Під час автоматичного чи ручного оновлення вміст розгорнутих гілок залишається видимим. Попередження біля гілки означає, що її вміст може бути застарілим. Оновіть панель, щоб повторити спробу.\n\nУвімкніть «Розміри папок», щоб обчислити суми в поточній панелі. Команда «Оновити» повторно перевіряє поточну папку та показує попередні значення до отримання нових. У дереві F3 вимірює розмір вибраної гілки разом із дочірніми папками. Три крапки означають очікування, риска — недоступний розмір, ≥ — часткову суму. «Розмір на диску», якщо доступний, показує виділене місце. Вимкніть розміри папок, щоб зупинити фонове сканування. Див. [[paneSelection|поточний рядок і позначки]] та [[spaceAnalyzer|аналізатор місця]].",
    workspace: "Головне меню видно за замовчуванням. Щоб показувати його лише за потреби, вимкніть «Завжди показувати головне меню» в розділі «Налаштування» → «Оформлення» → «Вікно». За замовчуванням F9 або Alt переводить фокус на меню. Використовуйте стрілки для навігації, Enter для запуску команди й Esc для повернення до попереднього елемента. У меню «Ліва» і «Права» доступні джерела, режими й сортування відповідної панелі. «Файли» діє на поточний або позначені елементи, «Команди» відкриває пошук, порівняння, закладки й спеціальні панелі. «Налаштування» змінює параметри. У меню довідки є цей посібник, примітки до випуску та журнал діагностики, якщо вони доступні. Відкрийте журнал через «Довідка» → «Відкрити журнал помилок», потім у переглядачі виберіть «Файл» → «Очистити журнал помилок» і підтвердьте. Нові помилки й далі записуватимуться. У розділі «Довідка» → «Про програму» натисніть ім’я автора, щоб відкрити hrynco.com у браузері. У випусках GitHub доступні пакети й оновлення для Windows, Linux і macOS. Щоб перевірити наявність оновлень вручну, виберіть «Команди» → «Перевірити оновлення». Якщо встановлено актуальну версію Dirlume, кнопка «Підтримати через monobank» відкриває банку Dirlume у браузері.\n\nПанель інструментів перемикає [[quickView|швидкий перегляд]], відкриває [[gitView|Git View]] для локального репозиторію, підключає джерела й запускає [[search|пошук файлів]]. Обмін панелями міняє їх місцями, якщо доступні обидві. Показ прихованих файлів діє в обох панелях. Термінал можна показати або сховати, коли документ закрито. Сонце та місяць перемикають улюблену світлу або темну схему. Список схем, якщо його ввімкнено, дає змогу вибрати будь-яку встановлену схему.\n\nПеретягніть розділювач панелей або сфокусуйте його і скористайтеся стрілками вліво та вправо. Розділювач термінала можна перетягнути вертикально. У Windows кнопки заголовка згортають, розгортають, відновлюють і закривають вікно. Рядок стану показує останню дію чи помилку й активне розташування. Див. [[operations|операції з файлами]] та [[files|основні файлові панелі]].\n\nПозначка «Адміністратор» поруч із назвою Dirlume вказує, що вікно Windows працює з підвищеними правами.",
    paneNavigation: "«Назад» повертає до попереднього розташування в цій панелі, а «Уперед» знову відкриває відвідане розташування. Якщо переходити нікуди, стрілка неактивна. «Назад» також повертає з результатів пошуку або списку процесів. Кнопка «Батьківська папка», рядок .. і налаштоване скорочення «Батьківська папка» відкривають папку на рівень вище. У локальній панелі Shift+Enter відкриває вибрану папку в системному файловому менеджері. На рядку .. команда відкриває поточну папку. Для файлів Shift+Enter діє так само, як Enter. У корені, зокрема в списку збережених підключень, кнопка неактивна, а рядок приховано. Щоб повернутися зі списку, натисніть «Назад» або приглушений сегмент.\n\nЩоб перейти до іншої папки, скористайтеся [[paneAddress|адресою та шляхом]]. Щоб змінити джерело, відкрийте [[paneSources|вибір диска та джерела]]. Оновлення перечитує поточну папку або повторює локальний пошук у [[search|результатах пошуку]]. Воно недоступне під час завантаження.",
    paneAddress: "Виділений сегмент показує поточну папку або список підключень. Натисніть попередній сегмент, щоб відкрити відповідну батьківську папку. Під час переходу до батьківської папки попередня гілка лишається доступною через приглушені сегменти. Три крапки на початку, «Показати батьківські папки», відкривають приховані батьківські папки. Три крапки в кінці, «Показати попередній шлях», відкривають приховані папки попередньої гілки. Розширте панель, щоб побачити приховані сегменти. У віддаленій панелі назва джерела в адресі та поточне джерело в меню панелі відкривають збережені підключення й залишають доступним попередній шлях. «Назад» повертає до попередньої папки, а «Вперед» знову відкриває список.\n\nНатисніть порожню область адреси або кнопку з олівцем, щоб ввести шлях. Стрілки дозволяють вибрати підказку, Enter відкриває введену чи вибрану папку. Esc відновлює сегменти. Кнопка копіювання переносить адресу до буфера обміну без переходу. Деякі джерела показують шлях лише для читання. Див. [[paneNavigation|навігацію панелі]] та [[paneSources|джерела панелі]].",
    paneSources: "Кнопка диска зі стрілкою поруч з адресою відкриває список джерел. Виберіть диск, збережену папку, тип з’єднання або процеси. Стрілки вгору й униз переміщаються списком, Enter підтверджує вибір, Esc закриває список. Типові Alt+F1 і Alt+F2 відкривають джерела лівої та правої панелей відповідно. Вони також доступні в меню «Ліва» та «Права».\n\nРозділ «Цей комп’ютер» містить локальні папки й диски. У Dirlume LAN показано комп’ютери, спарені безпосередньо в Dirlume. У KSwitcher LAN показано комп’ютери, спарені через KSwitcher, і повідомлення про дозволи для цього з’єднання.\n\nВиберіть «Недавні» під «Завантаженнями», щоб переглянути останні 100 відвіданих папок. Список спільний для обох панелей. Фільтруйте за назвою, шляхом або джерелом. Натисніть Enter або двічі клацніть папку, щоб відкрити її в цій панелі. Можна видалити вибрану папку з недавніх або очистити весь список.\n\nУ парних панелях і класичному режимі кнопки дисків розташовані над списком файлів. Виділений диск або місце містить поточну папку. SMB доступний у Windows, macOS та Ubuntu. Для підключення може знадобитися збережений профіль або дозвіл. Див. [[remote|віддалені з’єднання]] та [[files|основні файлові панелі]]. Виберіть «Колекції» або натисніть 6 у списку джерел, щоб відкрити збережені колекції. Створіть і назвіть колекцію, а тоді натисніть F7, щоб створити віртуальну папку. Щоб додати посилання, відкрийте папку колекції в одній панелі, виберіть файли або папки в іншій, натисніть F5 і підтвердьте віртуальне призначення. Після вилучення посилання чи віртуальної папки оригінали залишаються на місці. Щоб скопіювати поточний вміст оригіналів, виберіть посилання чи віртуальну папку й натисніть F5. Dirlume відтворить ієрархію в локальній папці та запропонує звичайні варіанти розв’язання конфліктів. Посилання на відсутні або тимчасово недоступні оригінали залишаються для повторної спроби.",
    paneFilter: "Фільтр папки обмежує видимий список поточної панелі збігами в цій папці, не обходячи вкладені папки. Введіть фільтр і натисніть Enter для повернення до списку. Esc або кнопка закриття очищує фільтр. Нуль елементів означає, що немає видимих збігів.\n\n[[search|Пошук файлів]] обходить вибрану область і відкриває окремий список результатів. Швидкий пошук переміщує курсор між видимими елементами, зберігаючи список і позначки. Див. [[files|основні файлові панелі]].",
    paneColumns: "Заголовки називають поля поточного режиму панелі. Натисніть заголовок із сортуванням, щоб змінити порядок. Стрілка показує поле й напрямок. Правою кнопкою або клавішею контекстного меню відкрийте вибір видимих стовпців. Назва залишається видимою. Стислий і середній режими групують елементи у стовпці та перегортають їх сторінками. Повний, широкий та інші режими показують різні поля.\n\nУ меню лівої або правої панелі виберіть режими сортування, щоб налаштувати ключі, групи й порядок за однакових значень. Поля залежать від можливостей джерела. Склад і ширину стовпців списку й рядка стану задають у налаштуваннях режимів панелі. Вбудовані режими використовують автоматичну ширину. Значення 0 підлаштовує ширину під заголовок і дані, коли в панелі є місце. Назва займає простір, що залишається після інших стовпців. Для власної розкладки задайте ширину в символах або відсотках. Стовпець розміру розширюється за потреби, щоб умістити виміряний розмір папки разом з одиницею виміру. Див. [[files|основні файлові панелі]].",
    paneSelection: "Поточний рядок — елемент під курсором. Переміщуйте його стрілками або швидким пошуком. Insert, Shift із клавішами вибору та Ctrl-клік або Command-клік позначають елементи. Якщо ввімкнено позначення правою кнопкою, коротке натискання перемикає позначку, перетягування застосовує дію першого рядка до кожного нового рядка навіть після зміни напрямку. Повторне проходження не змінює позначку. Утримання без руху відкриває меню після відпускання. Рядок .. не позначається. Позначені рядки зберігають іконки елементів і звичайну товщину тексту. Назви поточного й позначених елементів використовують колір тексту виділення зі схеми. Решта назв зберігають звичайні кольори файлів. Режим «Назва з позначкою» також показує галочку. Пробіл очищує всі позначки у файловому списку з фокусом і залишає поточний рядок. Команду «Очистити позначки» можна змінити або вимкнути в Налаштування → Клавіатурні скорочення.\n\nПакетні [[operations|операції з файлами]] застосовуються до позначених елементів активної панелі, а за відсутності позначок — до поточного елемента. Відкриття, переглядач, редактор і швидкий перегляд працюють із поточним файлом. Контур і тло поточного позначеного рядка можна змінити в [[panels|оформленні панелей]].",
    paneStatus: "У нижньому рядку можуть бути властивості поточного елемента, кількість видимих папок і файлів, кількість і загальний розмір позначених елементів. Знак ≥ означає нижню межу суми. Недоступні поля й часткові результати означають, що джерело надало неповні дані. У результатах пошуку показано кількість збігів.\n\nПерехід і обчислення розмірів мають індикатор поступу. Кнопка скасування зупиняє дію в цій панелі. Закриття помилки прибирає повідомлення. У разі відмови доступу Windows може запропонувати окреме вікно з підвищеними правами, а підтримуваний сеанс SSH — повтор із sudo. Індикатор вільного місця відкриває [[spaceScope|область аналізу]]. Див. [[files|основні файлові панелі]].\n\nПід час відкриття локального файла через систему тут показано очікування, коротке підтвердження передавання або повідомлення про помилку.",
    diskInformation: "Натисніть Ctrl+Shift+L, щоб побачити «Відомості про диск» для тому або змонтованого ресурсу активної папки в протилежній панелі. На macOS також працює Command+Shift+L. Повторне натискання закриває відомості й відновлює попередній вигляд цієї панелі. Вихідна папка залишається видимою. Комбінацію можна змінити або вимкнути в Налаштування → Клавіатурні скорочення.\n\nНазва, файлова система та місткість доступні без сканування файлів. Натисніть «Сканувати том» або «Сканувати ресурс», щоб виміряти зайняте місце в [[spaceAnalyzer|аналізаторі місця]].",
    spaceSunburst: "У центрі радіальної карти показано поточну папку. Внутрішнє кільце показує її елементи, зовнішнє — елементи вкладених папок. У списку наведено ті самі назви, розміри й частки. Виберіть папку для переходу або файл для перегляду відомостей. Правий клік або Shift+F10 відкриває дії. Вибраний режим зберігається для нових сканувань.",
    spaceAnalyzer: "Аналізатор місця сканує папку, том, спільний ресурс або корінь з’єднання у вибраній панелі. Для локальних APFS і ext4 сканування використовує швидше читання метаданих, якщо файлова система це підтримує. Це також прискорює сканування тому, підрахунок за F3 і фоновий підрахунок розмірів папок у списку й дереві. Виберіть «Аналізатор місця» в меню лівої або правої панелі. Див. [[spacePath|поточну папку]] та [[spaceScope|область сканування]]. Результати доступні як [[spaceTree|дерево]] або [[spaceTreemap|карта]]. Див. [[spaceMetric|спосіб обчислення розміру]].",
    spaceScope: "Натисніть «Аналізувати місце» або показник вільного місця, щоб просканувати відкриту папку. Якщо доступна місткість, шкала показує зайняту частку, а текст — вільний обсяг. Диски спарених комп’ютерів Dirlume та диски KSwitcher LAN показують ці дані, якщо віддалений комп’ютер повідомляє місткість. Наведіть вказівник на кнопку або перейдіть до неї клавішею Tab, щоб побачити вільне, загальне й зайняте місце. Стрілка дає змогу вибрати весь том, спільний ресурс або корінь з’єднання, якщо межу відомо. Перед запуском меню показує шлях.\n\n[[spaceAnalyzer|Аналізатор місця]] доступний для підтримуваних локальних папок і файлових серверів. Списки архівів та вибір з’єднань не підтримують сканування. У парних панелях кнопка над списком, в інших режимах — унизу.",
    spacePath: "Шлях показує поточну папку або батьківську папку вибраного файлу. Коли шлях вміщається, видно всі його частини. У вузькій панелі виберіть «Показати батьківські папки», щоб відкрити приховану папку. Виберіть батьківську папку, щоб показати її в дереві. Раніше відкриті гілки залишаться розгорнутими. Папка поза коренем запускає нове сканування. Ті самі правила діють після успішної зміни папки в локальному або відповідному SSH-терміналі.",
    spaceTree: "Дерево перелічує файли й папки під коренем. Виберіть рядок кліком або стрілками вгору й униз. Стрілка розкриття, подвійний клік по папці або стрілка вправо розгортають гілку. Стрілка вліво згортає її або переходить до батьківського рядка. Home та End переходять до першого й останнього видимих рядків. Розмір, шкала та відсоток залежать від [[spaceMetric|метрики]]. Див. [[spaceActions|дії й часткові результати]].\n\nУ локальному дереві натисніть файл або папку правою кнопкою, щоб відкрити дії. F5 копіює, F6 перейменовує або переносить, F8 діє за правилами кошика джерела, а Shift+Delete відкриває остаточне видалення. Діють ті самі налаштування клавіш, що й у файловій панелі. Корінь сканування не можна перемістити або видалити з дерева. Див. [[actionDialogs|діалоги файлових операцій]].",
    spaceTreemap: "Площа плитки показує розмір елемента в поточній папці за [[spaceMetric|вибраною метрикою]]. Натисніть плитку папки, щоб перейти в неї, або плитку файла, щоб вибрати його. Стрілка над картою повертає до батьківської папки. Заголовок показує поточну папку й суму. «Інші елементи» повертає до дерева, де видно також нульові й недоступні розміри. За відсутності додатних розмірів карта порожня. Див. [[spaceAnalyzer|аналізатор місця]].",
    spaceMetric: "Розмір файла — його логічна довжина. Розмір на диску — виділене сховище. Воно може бути більшим через блоки або меншим для стиснених і розріджених файлів. Деякі джерела надають лише логічний розмір. Перемикання доступної метрики оновлює підсумки, порядок, шкали й плитки. Спільно виділене місце для жорстких посилань рахується один раз.\n\nВідсоток — частка елемента в його батьківській папці за поточною метрикою. Однакові відсотки в різних папках можуть відповідати різній кількості байтів. Див. [[spaceActions|нульові й часткові значення]] та [[spaceAnalyzer|аналізатор місця]].",
    spaceActions: "«Сканування…» означає, що результати ще надходять. Підтверджені 0 Б означають відсутність байтів за вибраною метрикою. Риска означає недоступне значення. У часткових результатах можуть бракувати непрочитані або ще не проскановані гілки. Після обриву віддаленого зв’язку підключіться знову перед скануванням.\n\n«Зупинити» зберігає знайдені на цей момент елементи. «Сканувати повторно» починає з того самого кореня. «Показати в іншій панелі» відкриває вибрану папку або виділяє файл у батьківській папці. Після помилки всього сканування ця дія недоступна. «Закрити» завершує аналіз і повертає файлову панель. Див. [[spaceAnalyzer|аналізатор місця]].",
    quickView: "Швидкий перегляд показує поточний файл у протилежній панелі. Кнопки «Попередній файл» і «Наступний файл» переміщують курсор у вихідній панелі в порядку показу файлів, пропускають папки та зупиняються на краях списку. Типові скорочення — Alt+PageUp та Alt+PageDown. Кожне можна змінити або вимкнути в розділі «Налаштування» → «Клавіатурні скорочення». Для Markdown і HTML можна перемкнути оформлений або вихідний текст. Ctrl із коліщатком масштабує текст і діаграми Markdown разом. Виберіть «Відкрити діаграму», щоб переглянути її окремо. Двійкові файли показуються як байти зі зміщеннями. Для зображень доступні масштаб і вміщення в панель. Обертання змінює лише перегляд. Для непідтримуваних або недоступних файлів з’являється пояснення. Вимкніть швидкий перегляд, щоб повернути другу файлову панель, або відкрийте вкладку [[viewer|переглядача]].",
    gitView: "Git View відкривається з локальної папки Git. Панель гілок перелічує локальні та віддалені посилання й позначає поточну гілку. Фільтр обмежує список. Вибір гілки показує її історію у протилежній панелі без перемикання гілки. Розгорніть коміт, щоб переглянути відомості, змінені шляхи або скопіювати хеш. За наявності можна завантажити старіші записи. Виберіть «Зміни», щоб переглянути файли в індексі, поза індексом і невідстежувані файли в усьому робочому дереві. Фільтруйте за шляхом і вибирайте зміни стрілками вгору й униз. Протилежна панель показує рядкові відмінності. Зміни в індексі порівнюють HEAD з індексом, а зміни поза індексом порівнюють індекс із робочим файлом. Переглядач і редактор відкривають робочий файл, якщо він доступний. Збереження або оновлення перечитує зміни.\n\nВиберіть гілку-джерело й натисніть «Злити гілку». Перевірте гілку-джерело й поточну гілку та виберіть швидке перемотування або коміт злиття. «Триває злиття» показує конфлікти Git навіть після повторного відкриття застосунку. Порівняйте базову, нашу й їхню версії. Виберіть бік або відредагуйте робочий результат і додайте його до індексу. Після розв’язання всіх конфліктів продовжте злиття або підтвердьте його переривання.\n\nВідкрийте «Дії з історією», щоб перенести коміт, скасувати його зміни, скинути чи перебазувати гілку, переглянути журнал посилань або виконати примусовий push із перевіркою вершини. У відомостях про коміт натисніть «Вибрати для дій з історією», щоб підставити його ідентифікатор. Перевірте призначення та шляхи. Для перебазування виберіть базу, змініть порядок комітів і виберіть, які з них перенести, перейменувати, об’єднати чи вилучити. Після повторного відкриття Git View можна розв’язати конфлікти й продовжити або перервати призупинену операцію. Журнал посилань дозволяє відновити коміт у новій гілці. Перед примусовим push перевірте призначення й очікувану вершину віддаленої гілки.\n\nДії з гілками дають змогу створити локальну гілку з вибраного коміту, перейти на локальну гілку, перейменувати або безпечно видалити її чи створити локальну гілку відстеження і перейти на неї. Перед підтвердженням перевірте репозиторій і гілку.\n\nУ панелі історії виберіть «Порівняти ревізії». Виберіть гілки, теги або введіть повні ідентифікатори комітів. Порівняння показує унікальні коміти з обох боків та змінені шляхи від базової до цільової ревізії. Виберіть шлях для перегляду рядкових відмінностей. Робоча копія залишається без змін. Відкрийте «Граф комітів» для пошуку в повідомленнях вибраної гілки. В «Історії файлу» введіть шлях відносно репозиторію, щоб переглянути коміти або авторство рядків у вибраній ревізії.\n\nКоманди «Додати блок змін до індексу» та «Прибрати блок змін з індексу» дають змогу переглянути й змінити один текстовий блок. «Вибрати файли» відкриває перегляд кількох шляхів. «Відкинути» показує шлях і робочі зміни перед відновленням з індексу або видаленням невідстежуваного файла. «Замінити коміт» замінює поточний коміт після перевірки індексу й повідомлення. У вікні «Відкладені зміни» зберігайте робочі й підготовлені версії, переглядайте та застосовуйте їх або підтверджуйте вилучення. Щоб відновити індекс, увімкніть «Відновити підготовлені зміни в індексі». Залишкові конфлікти видно в Git View.\n\nУ панелі перегляду виберіть «Додати до індексу» або «Прибрати з індексу» для вибраного файла. Додавання записує поточну робочу версію й запитує підтвердження перед заміною версії в індексі. Вилучення відновлює запис в індексі й зберігає робочий файл. У розділі «Зміни» кнопка «Створити коміт» показує всі шляхи в індексі, зокрема приховані фільтром. Виберіть шлях, щоб переглянути зміни в індексі, введіть повідомлення й підтвердьте. Git створить локальний коміт у поточній гілці. Скасування зберігає чернетку в поточному сеансі Git View. Якщо індекс або гілка змінилися, перегляньте оновлений список перед новою спробою. Git виконує hooks і підписування за налаштуваннями репозиторію. Якщо потрібне введення даних, скористайтеся терміналом. Hook, який змінює вміст майбутнього коміту, зупиняє створення коміту. Закриття повертає [[files|файлові панелі]].",
    environment: "Виберіть область, щоб переглядати змінні й фільтрувати за іменем. Системна, користувацька й оболонкова області залежать від платформи. Заголовок сортує список. Швидкий пошук переміщує курсор між видимими рядками. Стрілка вгору повертає до областей, а «Назад до файлів» — до файлової панелі. Оновлення перечитує область.\n\n«Переглянути» читає значення. Редагування й створення записують у доступну для запису область і можуть потребувати дозволу. Копіювання до іншої доступної області використовує позначені змінні або поточну й дозволяє перевірити збіги перед записом. Інтеграція з оболонкою входу доступна на підтримуваних платформах. [[terminal|Термінал]] повідомляє, якщо середовище треба оновити.",
    actionDialogs: "Команди → Історія операцій із файлами показує останні копіювання й перенесення за сеанс. Скасувати або повторити можна операції з перевіреними звичайними локальними файлами, якщо вони мали одне місце призначення й не перезаписували файлів. Скасування копіювання переміщує створені копії до кошика. Якщо операція зупинилася частково, повторна спроба застосовується до решти файлів. Нова операція, що змінила файли, очищує можливість повторення.\n\nДіалог копіювання або перенесення показує вибрані елементи й призначення. Змініть шлях або скористайтеся вибором папки, якщо доступний. Прапорці під параметром обробки наявних файлів дають змогу, наприклад, зберегти часові мітки чи застосувати маску файлів. Кожен прапорець розташовано ліворуч від підпису. Натисніть підпис або клавішу Space, коли прапорець у фокусі. Під час завантаження перевірте підключення FTP або SFTP поруч зі шляхом. Якщо в іншій панелі відкрита папка SSH, F6 переносить до неї звичайні локальні файли. Кожен вихідний файл видаляється після завершення запису на сервері. Якщо видалення не вдалося, повторна спроба спочатку перевірить файл на сервері. Перейменування змінює ім’я в батьківській папці. Діалог конфлікту показує наявне призначення й доступні для цієї дії варіанти. Скасування залишає очікувану зміну незастосованою. Для тривалого копіювання або перенесення діалог через п’ять секунд оцінює залишок часу, якщо відомі розміри й швидкість передавання. Поки діалог конфлікту чекає вашого вибору, оцінку призупинено.\n\nПеренесення в кошик і остаточне видалення вимагають підтвердження. Пакетне видалення показує поточний елемент і лічильник. Після виправної помилки можна повторити спробу, пропустити або скасувати решту. У Windows блокування файла може відкрити список процесів. Див. [[operations|операції з файлами]] та [[paneSelection|курсор і позначки]].",
    fileBookmarks: "Натисніть біля номера рядка або виберіть «Додати закладку рядка» в переглядачі локального тексту. В оформленому Markdown виділіть уривок і виберіть «Навігація → Додати закладку виділення». Обидва режими використовують спільне налаштовуване скорочення. Кнопка «Закладки файлів» і команда «Команди → Закладки файлів» відкривають те саме вікно. Закладки згруповані за файлами, включно із закритими. Перетягніть вікно за заголовок. Воно залишається відкритим під час роботи в Dirlume та переходу до закладки. Виберіть запис і натисніть Enter, щоб відкрити рядок джерела або підсвітити уривок у перегляді. Якщо уривок не знайдено, закладка лишається в списку. У списку можна перейменувати або видалити закладку.",
  },
  ru: {
    paneViews: "Список показывает открытую папку. Дерево раскрывает ветви в той же панели. Используйте кнопку раскрытия или настроенные клавиши влево и вправо. Каждая панель запоминает свой вид. Возврат к списку из вложенного элемента открывает его родительскую папку и сохраняет выбор, если элемент доступен. Если родительскую папку открыть не удалось, список показывает папку, уже открытую в панели. Дерево и фоновые размеры доступны для локальных папок. При автоматическом или ручном обновлении содержимое раскрытых ветвей остаётся видимым. Предупреждение у ветви означает, что её содержимое могло устареть. Обновите панель, чтобы повторить попытку.\n\nВключите «Размеры папок», чтобы рассчитать размеры в текущей панели. Команда «Обновить» повторно проверяет текущую папку и показывает прежние значения до получения новых. В дереве F3 измеряет размер выбранной ветви вместе с дочерними папками. Многоточие означает ожидание, тире — недоступный размер, ≥ — частичный итог. «Размер на диске», если доступен, показывает выделенное место. Отключите размеры папок, чтобы остановить фоновое сканирование. См. [[paneSelection|текущую строку и отметки]] и [[spaceAnalyzer|анализатор места]].",
    workspace: "Главное меню видно по умолчанию. Чтобы показывать его только при необходимости, выключите «Всегда показывать главное меню» в разделе «Настройки» → «Оформление» → «Окно». По умолчанию F9 или Alt переводит фокус на меню. Используйте стрелки для навигации, Enter для запуска команды и Esc для возврата к предыдущему элементу. «Левая» и «Правая» содержат источники, режимы и сортировку панели. «Файлы» работает с текущим или отмеченными элементами. «Команды» открывает поиск, сравнение, закладки и специальные панели. «Настройки» меняет параметры. В меню справки доступны это руководство, примечания к выпуску и журнал диагностики, если они есть. Откройте журнал через «Справка» → «Открыть журнал ошибок», затем в просмотрщике выберите «Файл» → «Очистить журнал ошибок» и подтвердите. Новые ошибки продолжат записываться. В разделе «Справка» → «О программе» нажмите на имя автора, чтобы открыть hrynco.com в браузере. В выпусках GitHub доступны пакеты и обновления для Windows, Linux и macOS. Для ручной проверки выберите «Команды» → «Проверить обновления». Если установлена актуальная версия Dirlume, кнопка «Поддержать через monobank» открывает банку Dirlume в браузере.\n\nПанель инструментов переключает [[quickView|быстрый просмотр]], открывает [[gitView|Git View]] локального репозитория и запускает [[search|поиск файлов]]. Обмен меняет панели местами, когда доступны обе. Показ скрытых файлов действует в обеих панелях. Терминал можно показать и скрыть, когда документ закрыт. Солнце и луна переключают любимую светлую или тёмную схему. Включённый список схем позволяет выбрать любую установленную схему.\n\nПеретащите разделитель панелей или сфокусируйте его и нажимайте стрелки влево и вправо. Разделитель терминала можно перетащить вертикально. В Windows кнопки заголовка сворачивают, разворачивают, восстанавливают и закрывают окно. Строка состояния показывает последнее действие или ошибку и активное расположение. См. [[operations|операции с файлами]] и [[files|основные файловые панели]].\n\nМетка «Администратор» рядом с названием Dirlume указывает, что окно Windows работает с повышенными правами.",
    paneNavigation: "«Назад» возвращает к предыдущему расположению в этой панели, а «Вперёд» снова открывает посещённое расположение. Стрелка неактивна, когда переходить некуда. «Назад» также возвращает из результатов поиска или списка процессов. Кнопка «Родительская папка», строка .. и настроенное сочетание клавиш «Родительская папка» открывают папку на уровень выше. В локальной панели Shift+Enter открывает выбранную папку в системном файловом менеджере. На строке .. команда открывает текущую папку. Для файлов Shift+Enter действует так же, как Enter. В корне, в том числе в списке сохранённых подключений, кнопка неактивна, а строка скрыта. Чтобы вернуться из списка, нажмите «Назад» или приглушённый сегмент.\n\nИспользуйте [[paneAddress|адрес и путь]] для перехода в другую папку или [[paneSources|диски и источники]] для смены источника. Обновление перечитывает папку или повторяет локальный поиск в [[search|результатах поиска]]. Оно недоступно во время загрузки.",
    paneAddress: "Выделенный сегмент показывает текущую папку или список подключений. Нажмите предыдущий сегмент, чтобы открыть соответствующую родительскую папку. При переходе к родительской папке предыдущая ветвь остаётся доступной через приглушённые сегменты. Многоточие в начале, «Показать родительские папки», открывает скрытые родительские папки. Многоточие в конце, «Показать предыдущий путь», открывает скрытые папки предыдущей ветви. Расширьте панель, чтобы увидеть скрытые сегменты. В удалённой панели имя источника в адресе и текущий источник в меню панели открывают сохранённые подключения и сохраняют предыдущий путь. «Назад» возвращает в предыдущую папку, а «Вперёд» снова открывает список.\n\nНажмите пустую область адреса или кнопку с карандашом, чтобы ввести путь. Стрелками можно выбрать подсказку, Enter открывает введённую или выбранную папку. Esc восстанавливает сегменты. Кнопка копирования помещает адрес в буфер обмена без перехода. В некоторых источниках адрес доступен только для чтения. См. [[paneNavigation|навигацию панели]] и [[paneSources|выбор источника]].",
    paneSources: "Кнопка диска со стрелкой возле адреса открывает выбор источника. Выберите диск, сохранённую папку, тип соединения или процессы. Стрелки вверх и вниз перемещают курсор между пунктами, Enter выбирает, Esc закрывает список. Alt+F1 и Alt+F2 по умолчанию открывают источники левой и правой панелей. Выбор также есть в меню «Левая» и «Правая».\n\nРаздел «Этот компьютер» содержит локальные папки и диски. В Dirlume LAN показаны компьютеры, сопряжённые напрямую через Dirlume. В KSwitcher LAN показаны компьютеры, сопряжённые через KSwitcher, и сообщения о разрешениях для этого соединения.\n\nВыберите «Недавние» под пунктом «Загрузки», чтобы увидеть последние 100 посещённых папок. Список общий для обеих панелей. Фильтруйте по имени, пути или источнику. Нажмите Enter или дважды щёлкните папку, чтобы открыть её в этой панели. Можно удалить выбранную папку из недавних или очистить весь список.\n\nВ парных панелях и классическом режиме кнопки дисков расположены над списком. Выделенный диск или расположение содержит текущую папку. SMB доступен в Windows, macOS и Ubuntu. Для соединения может потребоваться профиль или разрешение. См. [[remote|удалённые соединения]] и [[files|основные файловые панели]]. Выберите «Коллекции» или нажмите 6 в списке источников, чтобы открыть сохранённые коллекции. Создайте и назовите коллекцию, затем нажмите F7 для создания виртуальной папки. Чтобы добавить ссылки, откройте папку коллекции в одной панели, выберите файлы или папки в другой, нажмите F5 и подтвердите виртуальную папку назначения. Удаление ссылки или виртуальной папки сохраняет оригиналы. Чтобы скопировать текущее содержимое оригиналов, выберите ссылки или виртуальную папку и нажмите F5. Dirlume воссоздаст иерархию в локальной папке и предложит обычные способы разрешения конфликтов. Ссылки на отсутствующие или временно недоступные оригиналы остаются для повторной попытки.",
    paneFilter: "Фильтр папки оставляет в текущей панели совпадения из текущей папки без обхода вложенных папок. Введите фильтр и нажмите Enter для возврата к списку. Esc или кнопка закрытия очищает фильтр. Ноль элементов означает отсутствие видимых совпадений.\n\n[[search|Поиск файлов]] обходит выбранную область и показывает совпадения отдельно. Быстрый поиск перемещает курсор среди видимых элементов, сохраняя список и отметки. См. [[files|основные файловые панели]].",
    paneColumns: "Заголовки называют поля текущего режима панели. Нажмите заголовок с сортировкой, чтобы изменить порядок. Стрелка обозначает поле и направление. Правая кнопка или клавиша контекстного меню открывает выбор видимых столбцов. Имя остаётся видимым. Краткий и средний режимы группируют элементы в столбцы и листают их страницами. Полный, широкий и другие режимы показывают разные поля.\n\nРежимы сортировки в меню левой или правой панели задают ключи, группы и порядок при равенстве. Состав полей зависит от источника. В настройках режимов панели можно менять поля и ширину списка и строки состояния. Встроенные режимы используют автоматическую ширину. Значение 0 подбирает ширину по заголовку и данным, когда в панели есть место. Имя занимает пространство, оставшееся после других столбцов. Для собственной раскладки задайте ширину в символах или процентах. Столбец размера при необходимости расширяется, чтобы вместить измеренный размер папки вместе с единицей измерения. См. [[files|основные файловые панели]].",
    paneSelection: "Текущая строка — элемент под курсором. Перемещайте его стрелками или быстрым поиском. Insert, Shift с клавишами выбора и Ctrl-клик или Command-клик отмечают элементы. При включённой отметке правой кнопкой короткое нажатие переключает отметку, перетаскивание применяет действие первой строки к каждой новой строке даже при смене направления. Повторный проход сохраняет отметку. Удержание без движения открывает меню после отпускания. Строка .. не отмечается. Отмеченные строки сохраняют значки элементов и обычную толщину текста. Названия текущего и отмеченных элементов используют цвет текста выделения из схемы. Остальные названия сохраняют обычные цвета файлов. Режим «Имя с отметкой» также показывает галочку. Пробел снимает все отметки в списке файлов с фокусом и сохраняет текущую строку. Команду «Снять все отметки» можно изменить или отключить в Настройки → Сочетания клавиш.\n\nПакетные [[operations|операции с файлами]] используют отмеченные элементы активной панели, а при отсутствии отметок — текущий элемент. Открытие, просмотр, редактор и быстрый просмотр работают с текущим файлом. Контур и фон текущей отмеченной строки задаются в [[panels|оформлении панелей]].",
    paneStatus: "В нижней строке могут отображаться сведения о текущем элементе, число видимых папок и файлов, число и общий размер отмеченных элементов. Значок ≥ указывает нижнюю границу суммы. Недоступные поля и частичные результаты означают, что источник предоставил неполные данные. Для поиска указывается число совпадений.\n\nНавигация и расчёт размеров показывают ход работы. Кнопка отмены останавливает действие в этой панели. Закрытие ошибки убирает сообщение. При отказе в доступе Windows может предложить отдельное окно с повышенными правами, а поддерживаемый сеанс SSH — повтор с sudo. Индикатор свободного места открывает [[spaceScope|выбор области анализа]]. См. [[files|основные файловые панели]].\n\nПри открытии локального файла через систему здесь отображается ожидание, краткое подтверждение передачи или сообщение об ошибке.",
    diskInformation: "Нажмите Ctrl+Shift+L, чтобы увидеть «Сведения о диске» для тома или смонтированного ресурса активной папки в противоположной панели. В macOS также работает Command+Shift+L. Повторное нажатие закрывает сведения и восстанавливает предыдущий вид этой панели. Исходная папка остаётся видимой. Сочетание можно изменить или отключить в Настройки → Сочетания клавиш.\n\nНазвание, файловая система и ёмкость доступны без сканирования файлов. Нажмите «Сканировать том» или «Сканировать ресурс», чтобы измерить занятое место в [[spaceAnalyzer|анализаторе места]].",
    spaceSunburst: "В центре радиальной карты показана текущая папка. Внутреннее кольцо показывает её элементы, внешнее — содержимое вложенных папок. В списке приведены те же имена, размеры и доли. Выберите папку для перехода или файл для просмотра сведений. Правая кнопка мыши или Shift+F10 открывает действия. Выбранный режим сохраняется для новых сканирований.",
    spaceAnalyzer: "Анализатор места сканирует папку, том, общий ресурс или корень соединения в выбранной панели. Для локальных APFS и ext4 сканирование использует ускоренное чтение метаданных, если файловая система это поддерживает. Это также ускоряет сканирование тома, подсчёт по F3 и фоновый подсчёт размеров папок в списке и дереве. Откройте его из меню левой или правой панели. См. [[spacePath|текущую папку]] и [[spaceScope|область сканирования]]. Результаты доступны как [[spaceTree|дерево]] или [[spaceTreemap|карта]]. См. [[spaceMetric|способ измерения размера]].",
    spaceScope: "Нажмите «Анализировать место» или показание свободного места, чтобы просканировать открытую папку. Если известна ёмкость, шкала показывает занятую долю, а текст — свободный объём. Диски сопряжённых компьютеров Dirlume и диски KSwitcher LAN показывают эти данные, если удалённый компьютер сообщает ёмкость. Наведите указатель на кнопку или перейдите к ней клавишей Tab, чтобы увидеть свободное, общее и занятое место. Стрелка позволяет выбрать весь том, общий ресурс или корень соединения, если граница известна. Меню показывает путь перед запуском.\n\n[[spaceAnalyzer|Анализатор места]] доступен для поддерживаемых локальных папок и файловых серверов. Списки архивов и выбор соединений не поддерживают сканирование. В парных панелях кнопка расположена над списком, в других режимах — внизу.",
    spacePath: "Путь показывает текущую папку или родительскую папку выбранного файла. Если путь помещается, видны все его части. В узкой панели выберите «Показать родительские папки», чтобы открыть скрытую папку. Выберите родительскую папку, чтобы показать её в дереве. Уже раскрытые ветви сохраняются. Папка за пределами корня запускает новое сканирование. Те же правила действуют после успешной смены папки в локальном или соответствующем SSH-терминале.",
    spaceTree: "Дерево перечисляет файлы и папки под корнем. Выберите строку щелчком или стрелками вверх и вниз. Стрелка раскрытия, двойной щелчок по папке или стрелка вправо раскрывают ветвь. Стрелка влево сворачивает её или переходит к родительской строке. Home и End переходят к первой и последней видимой строке. Размер, шкала и доля зависят от [[spaceMetric|метрики]]. См. [[spaceActions|действия и частичные результаты]].\n\nВ локальном дереве нажмите файл или папку правой кнопкой для выбора действия. F5 копирует, F6 переименовывает или переносит, F8 действует по правилам корзины источника, а Shift+Delete открывает безвозвратное удаление. Действуют те же настройки клавиш, что и в файловой панели. Корень сканирования нельзя перемещать или удалять из дерева. См. [[actionDialogs|диалоги файловых операций]].",
    spaceTreemap: "Площадь плитки показывает размер элемента текущей папки по [[spaceMetric|выбранной метрике]]. Нажмите плитку папки для входа в неё, а плитку файла для выбора. Стрелка над картой возвращает к родительской папке. Заголовок содержит имя текущей папки и её размер. «Другие элементы» возвращает к дереву, где видны и элементы с нулевым или недоступным размером. При отсутствии положительных размеров карта пуста. См. [[spaceAnalyzer|анализатор места]].",
    spaceMetric: "Размер файла — его логическая длина. Размер на диске — выделенное хранилище. Оно может быть больше из-за блоков или меньше для сжатых и разрежённых файлов. Некоторые источники предоставляют только логический размер. Переключение метрики меняет итоги, порядок, шкалы и плитки. Общее выделенное место для жёстких ссылок учитывается один раз.\n\nПроцент — доля элемента в его родительской папке по текущей метрике. Одинаковые проценты в разных папках могут соответствовать разному числу байт. См. [[spaceActions|нулевые и частичные значения]] и [[spaceAnalyzer|анализатор места]].",
    spaceActions: "«Сканирование…» означает, что результаты ещё поступают. Полные 0 Б означают отсутствие байт по выбранной метрике. Тире обозначает недоступное значение. В частичных результатах могут отсутствовать нечитаемые или незаконченные ветви. После обрыва удалённого соединения подключитесь заново перед сканированием.\n\n«Остановить» сохраняет найденное. «Сканировать заново» повторяет сканирование от того же корня. «Показать в другой панели» открывает выбранную папку или выделяет файл в родительской папке. После ошибки всего сканирования действие недоступно. «Закрыть» завершает анализ и возвращает файловую панель. См. [[spaceAnalyzer|анализатор места]].",
    quickView: "Быстрый просмотр показывает текущий файл в противоположной панели. Кнопки «Предыдущий файл» и «Следующий файл» перемещают курсор в исходной панели в порядке показа файлов, пропускают папки и останавливаются на краях списка. По умолчанию действуют Alt+PageUp и Alt+PageDown. Каждое сочетание можно изменить или отключить в разделе «Настройки» → «Сочетания клавиш». Для Markdown и HTML можно выбрать оформленный или исходный текст. Ctrl с колёсиком масштабирует текст и диаграммы Markdown вместе. Выберите «Открыть диаграмму», чтобы просмотреть её отдельно. Двоичные файлы показывают байты и смещения. Для изображения доступны масштаб и вписывание в панель. Поворот меняет только предпросмотр. При неподдерживаемом или недоступном файле появляется пояснение. Закройте быстрый просмотр, чтобы вернуть вторую панель, или откройте вкладку [[viewer|просмотра]].",
    gitView: "Git View открывается из локальной папки Git. Панель ветвей перечисляет локальные и удалённые ссылки и отмечает текущую ветвь. Фильтр ограничивает список. Выбор ветви показывает её историю в другой панели без переключения ветви. Разверните коммит, чтобы посмотреть сведения, изменённые пути или скопировать хеш. Можно загрузить более старые записи, если они есть. Выберите «Изменения», чтобы просмотреть файлы в индексе, вне индекса и неотслеживаемые файлы во всём рабочем дереве. Фильтруйте по пути и выбирайте изменения стрелками вверх и вниз. Другая панель показывает построчные различия. Изменения в индексе сравниваются с HEAD, а изменения вне индекса сравнивают индекс с рабочим файлом. Просмотрщик и редактор открывают рабочий файл, если он доступен. Сохранение или обновление перечитывает изменения.\n\nВыберите исходную ветку и нажмите «Слить ветку». Проверьте исходную и текущую ветки и выберите перемотку вперёд или коммит слияния. «Идёт слияние» показывает конфликты Git даже после повторного открытия приложения. Сравните базовую, нашу и их версию. Выберите сторону или отредактируйте рабочий результат и добавьте его в индекс. После разрешения всех конфликтов продолжите слияние или подтвердите его отмену.\n\nОткройте «Действия с историей», чтобы перенести коммит, отменить его изменения, сбросить или перебазировать ветку, просмотреть журнал ссылок или выполнить принудительный push с проверкой вершины. В сведениях о коммите нажмите «Выбрать для действий с историей», чтобы подставить его идентификатор. Проверьте назначение и пути. Для перебазирования выберите базу, измените порядок коммитов и укажите, какие коммиты перенести, переименовать, объединить или исключить. После повторного открытия Git View можно разрешить конфликты и продолжить или прервать приостановленную операцию. Журнал ссылок позволяет восстановить коммит в новой ветке. Перед принудительным push проверьте назначение и ожидаемую вершину удалённой ветки.\n\nДействия с ветками позволяют создать локальную ветку из выбранного коммита, перейти на локальную ветку, переименовать или безопасно удалить её либо создать локальную ветку отслеживания и перейти на неё. Перед подтверждением проверьте репозиторий и ветку.\n\nВ панели истории выберите «Сравнить ревизии». Выберите ветки, теги или введите полные идентификаторы коммитов. Сравнение показывает уникальные коммиты с обеих сторон и изменённые пути от базовой до целевой ревизии. Выберите путь для просмотра построчных различий. Рабочая копия остаётся без изменений. Откройте «Граф коммитов» для поиска по сообщениям выбранной ветки. В «Истории файла» введите путь относительно репозитория для просмотра коммитов или авторства строк в выбранной ревизии.\n\nКоманды «Добавить блок изменений в индекс» и «Убрать блок изменений из индекса» позволяют просмотреть и изменить один текстовый блок. «Выбрать файлы» открывает просмотр нескольких путей. «Отбросить» показывает путь и рабочие изменения перед восстановлением из индекса или удалением неотслеживаемого файла. «Заменить коммит» заменяет текущий коммит после проверки индекса и сообщения. В окне «Отложенные изменения» сохраняйте рабочие и подготовленные версии, просматривайте и применяйте их или подтверждайте удаление. Чтобы восстановить индекс, включите «Восстановить подготовленные изменения в индексе». Оставшиеся конфликты видны в Git View.\n\nВ панели просмотра выберите «Добавить в индекс» или «Убрать из индекса» для выбранного файла. Добавление записывает текущую рабочую версию и запрашивает подтверждение перед заменой версии в индексе. Удаление восстанавливает запись в индексе и сохраняет рабочий файл. В разделе «Изменения» кнопка «Создать коммит» показывает все пути в индексе, включая скрытые фильтром. Выберите путь для проверки изменений в индексе, введите сообщение и подтвердите. Git создаст локальный коммит в текущей ветке. Отмена сохраняет черновик в текущем сеансе Git View. Если индекс или ветка изменились, просмотрите обновлённый список перед повторной попыткой. Git выполняет hooks и подписывание по настройкам репозитория. Если требуется ввод данных, используйте терминал. Hook, который изменяет содержимое будущего коммита, останавливает создание коммита. Закрытие возвращает [[files|файловые панели]].",
    environment: "Выберите область, чтобы просматривать переменные и фильтровать по имени. Системная, пользовательская и оболочечная области зависят от платформы. Заголовок сортирует список. Быстрый поиск перемещает курсор по видимым строкам. Стрелка вверх возвращает к областям, «Назад к файлам» — к файловой панели. Обновление перечитывает область.\n\nПросмотр читает значение. Редактирование и создание записывают в доступную область и могут требовать разрешения. Копирование в другую записываемую область использует отмеченные переменные или текущую и позволяет проверить совпадения до сохранения. Интеграция с оболочкой входа есть на поддерживаемых платформах. [[terminal|Терминал]] сообщает, когда нужно обновить окружение.",
    actionDialogs: "Команды → История операций с файлами показывает последние копирования и переносы за сеанс. Отменять или повторять можно операции с проверенными обычными локальными файлами, если у них было одно место назначения и они не перезаписывали файлы. Отмена копирования перемещает созданные копии в корзину. Если операция остановилась частично, повторная попытка применяется к оставшимся файлам. Новая операция, изменившая файлы, очищает возможность повтора.\n\nОкно копирования или переноса показывает выбранные элементы и место назначения. Измените путь или воспользуйтесь выбором папки, если он доступен. Флажки под настройкой обработки существующих файлов позволяют, например, сохранить отметки времени или применить маску файлов. Каждый флажок расположен слева от подписи. Нажмите подпись или клавишу Space, когда флажок в фокусе. При загрузке проверьте подключение FTP или SFTP рядом с путём. Если в другой панели открыта папка SSH, F6 перемещает в неё обычные локальные файлы. Каждый исходный файл удаляется после завершения записи на сервере. Если удаление не удалось, повторная попытка сначала проверит файл на сервере. Переименование меняет имя в родительской папке. Окно конфликта показывает существующее место назначения и доступные действия. Отмена оставляет ожидаемое изменение неприменённым. При длительном копировании или переносе диалог через пять секунд оценивает оставшееся время, если известны размеры и скорость передачи. Пока диалог конфликта ждёт вашего выбора, оценка приостановлена.\n\nПеремещение в корзину и окончательное удаление требуют подтверждения. Пакетное удаление показывает текущий элемент и счётчик. После исправимой ошибки можно повторить, пропустить или отменить оставшееся. В Windows блокировка файла может открыть список процессов. См. [[operations|операции с файлами]] и [[paneSelection|курсор и отметки]].",
    fileBookmarks: "Нажмите рядом с номером строки или выберите «Добавить закладку строки» в просмотрщике локального текста. В оформленном Markdown выделите отрывок и выберите «Навигация → Добавить закладку выделения». В обоих режимах действует одно настраиваемое сочетание. Кнопка «Закладки файлов» и команда «Команды → Закладки файлов» открывают одно окно. Закладки сгруппированы по файлам, включая закрытые. Перетащите окно за заголовок. Оно остаётся открытым во время работы в Dirlume и перехода к закладке. Выберите запись и нажмите Enter, чтобы открыть строку исходника или подсветить отрывок в просмотре. Если отрывок не найден, закладка остаётся в списке. В списке можно переименовать или удалить закладку.",
  },
};
